import{_ as t,o as i,c as s,ag as e}from"./chunks/framework.DoUXNnsN.js";const k=JSON.parse('{"title":"计算机组成","description":"","frontmatter":{"title":"计算机组成","aliases":["计算机组成原理","计算机体系结构入门","冯·诺依曼结构"],"tags":["计算机基础","计算机组成"],"status":"ai-draft","sources":["https://en.wikipedia.org/wiki/Von_Neumann_architecture","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":1},"headers":[],"relativePath":"10-计算机基础/计算机组成/计算机组成.md","filePath":"10-计算机基础/计算机组成/计算机组成.md"}'),l={name:"10-计算机基础/计算机组成/计算机组成.md"};function n(r,a,h,o,d,p){return i(),s("div",null,[...a[0]||(a[0]=[e(`<blockquote><p>本篇是&quot;计算机组成&quot;小系列的总览页。读完你应该能：画出一台计算机由哪几个部件组成、数据在它们之间怎么流动；知道接下来先看哪篇、再看哪篇。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>计算机组成讲的是：一台计算机里有哪些硬件部件（CPU、内存、存储、输入输出），它们怎样配合，才能把一串&quot;指令&quot;变成结果。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li>知道二进制和十六进制：<a href="/Encyclopedia/10-计算机基础/数据表示/十六进制">十六进制</a>、<a href="/Encyclopedia/10-计算机基础/数据表示/整数与补码">整数与补码</a>。简单说，计算机里所有东西（数字、文字、程序）最后都是 0 和 1。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>写程序时你只看到变量、函数、数据库。但程序慢、卡、崩溃，原因经常在硬件那一层：</p><ul><li>为什么同样的循环，换一种访问顺序就慢 5 倍？（缓存）</li><li>为什么电脑内存满了也不立刻崩溃，只是变卡？（见 <a href="/Encyclopedia/10-计算机基础/操作系统/内存管理与虚拟内存">内存管理与虚拟内存</a>）</li><li>为什么 4 核 CPU 不能让一个程序自动快 4 倍？（见 <a href="/Encyclopedia/10-计算机基础/操作系统/进程与线程">进程与线程</a>）</li><li>工控机、PLC 和普通电脑本质上有什么共同点？它们都是这套结构的变体。</li></ul><p>懂了组成，你就有了判断&quot;慢在哪里&quot;的地图。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="五大部件" tabindex="-1">五大部件 <a class="header-anchor" href="#五大部件" aria-label="Permalink to &quot;五大部件&quot;">​</a></h3><p>现代计算机几乎都沿用 1945 年前后提出的<strong>冯·诺依曼结构</strong>，它有两个关键思想：</p><ol><li><strong>程序也是数据</strong>：指令和数据都存在同一个存储器里，所以可以随时换程序。</li><li><strong>按顺序一条条执行指令</strong>：CPU 靠一个计数器指向&quot;下一条指令&quot;。</li></ol><p>五个部件：</p><table tabindex="0"><thead><tr><th>部件</th><th>作用</th><th>类比（一间厨房）</th></tr></thead><tbody><tr><td>运算器</td><td>做加减乘除、比较</td><td>厨师的手</td></tr><tr><td>控制器</td><td>读指令，指挥各部件</td><td>厨师的大脑，照菜谱办事</td></tr><tr><td>存储器</td><td>放程序和数据</td><td>菜谱和食材</td></tr><tr><td>输入设备</td><td>把外界信息送进来</td><td>点菜的客人</td></tr><tr><td>输出设备</td><td>把结果送出去</td><td>上菜</td></tr></tbody></table><p>运算器 + 控制器合起来就是 <strong>CPU</strong>（中央处理器）。存储器在实际中分好几层，见 <a href="/Encyclopedia/10-计算机基础/计算机组成/内存与存储层次">内存与存储层次</a>。</p><h3 id="数据怎么流动" tabindex="-1">数据怎么流动 <a class="header-anchor" href="#数据怎么流动" aria-label="Permalink to &quot;数据怎么流动&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 输入设备（键盘/传感器/网卡）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span> ┌──────────────┐  地址/数据/控制总线  ┌──────────────┐</span></span>
<span class="line"><span> │     CPU      │◄───────────────────►│  内存 (RAM)  │</span></span>
<span class="line"><span> │ 运算器+控制器 │                     └──────┬───────┘</span></span>
<span class="line"><span> └──────────────┘                            │</span></span>
<span class="line"><span>        │                                     ▼</span></span>
<span class="line"><span>        ▼                              外存（SSD/硬盘）</span></span>
<span class="line"><span> 输出设备（显示器/打印机/执行器）</span></span></code></pre></div><p><strong>总线</strong>就是连接各部件的一组导线，分地址线（说&quot;要哪个位置&quot;）、数据线（传内容）、控制线（说&quot;读还是写&quot;）。</p><h3 id="一台真实电脑的对应物" tabindex="-1">一台真实电脑的对应物 <a class="header-anchor" href="#一台真实电脑的对应物" aria-label="Permalink to &quot;一台真实电脑的对应物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>抽象部件</th><th>本机常见实物</th></tr></thead><tbody><tr><td>CPU</td><td>Intel/AMD 处理器，多个核心</td></tr><tr><td>内存</td><td>内存条（DDR 系列）</td></tr><tr><td>外存</td><td>固态硬盘 SSD、机械硬盘 HDD</td></tr><tr><td>输入输出</td><td>键盘、显示器、网卡、USB、工控机上的串口（见 <a href="/Encyclopedia/70-工业通信与自动化/串口通信">串口通信</a>）</td></tr></tbody></table><h2 id="逐步例子-一条语句经过哪些部件" tabindex="-1">逐步例子：一条语句经过哪些部件 <a class="header-anchor" href="#逐步例子-一条语句经过哪些部件" aria-label="Permalink to &quot;逐步例子：一条语句经过哪些部件&quot;">​</a></h2><p>假设程序里有 <code>total = price * qty</code>，price=8，qty=250。</p><ol><li>程序文件原本躺在硬盘（外存）里，运行时被读入内存。</li><li>CPU 的控制器按 PC（程序计数器）的地址，从内存取出第一条指令&quot;把 price 读进寄存器&quot;。</li><li>再取下一条&quot;把 qty 读进另一个寄存器&quot;。</li><li>运算器执行乘法：8 × 250 = 2000，结果放在寄存器。</li><li>最后一条指令把 2000 写回内存里 <code>total</code> 对应的地址。</li><li>如果要显示，再通过输出设备送出去。</li></ol><p>每一步的细节在 <a href="/Encyclopedia/10-计算机基础/计算机组成/CPU与指令执行">CPU与指令执行</a> 里，你会亲手写一个会执行指令的玩具 CPU。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><p>看看本机的 CPU 核心数和内存大小（PowerShell）：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-CimInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Win32_Processor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NumberOfCores</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NumberOfLogicalProcessors</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-CimInstance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Win32_OperatingSystem </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> @</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;内存GB&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">math</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]::Round(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.TotalVisibleMemorySize</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MB,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)}}</span></span></code></pre></div><p>本机实测：Intel Core Ultra 7 255H，16 个核心、16 个逻辑处理器，可见内存 31.4 GB。你的机器会不同，这很正常。用 Python 也能看逻辑处理器数（本机输出 16）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python -I -X utf8 -c &quot;import os; print(os.cpu_count())&quot;</span></span></code></pre></div><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>事实</th></tr></thead><tbody><tr><td>内存和硬盘都是&quot;存储&quot;，没区别</td><td>内存断电就丢、快几个数量级；硬盘断电保留、慢。见 <a href="/Encyclopedia/10-计算机基础/计算机组成/内存与存储层次">内存与存储层次</a></td></tr><tr><td>CPU 主频越高一定越快</td><td>还要看核心数、缓存、指令效率；程序若在等内存/磁盘，主频再高也没用</td></tr><tr><td>32 位、64 位只是个名字</td><td>位数决定一次能处理多宽的数据和能寻址多大内存（32 位约 4 GB 地址空间），见 <a href="/Encyclopedia/10-计算机基础/数据表示/整数与补码">整数与补码</a></td></tr></tbody></table><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><ul><li><strong>业务视角</strong>：工厂里的 MES 服务器、产线工控机、扫码枪背后的小电脑，都遵循这个结构。选型时的&quot;CPU、内存、硬盘怎么配&quot;就来自本篇的概念。</li><li><strong>技术视角</strong>：数据库服务器通常是&quot;内存不够就慢&quot;（缓存命中率），报表查询是&quot;磁盘读太多&quot;；这些问题用本系列的分层思想就能定位。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><ol><li>冯·诺依曼结构的两个关键思想是什么？ <strong>答</strong>：程序和数据都存放在存储器里（程序即数据）；CPU 按顺序一条条取指令执行。</li><li>CPU 由哪两部分组成？ <strong>答</strong>：运算器和控制器。</li><li>总线上的地址线、数据线、控制线分别负责什么？ <strong>答</strong>：说明访问哪个位置；传输内容；表示读/写等动作。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>计算机 = CPU（运算器+控制器）+ 存储器 + 输入输出，由总线连接。</li><li>程序和数据一起放在存储器，CPU 按顺序取指令执行。</li><li>所谓&quot;性能&quot;，常常取决于数据离 CPU 有多远。</li></ul><h2 id="入门路径" tabindex="-1">入门路径 <a class="header-anchor" href="#入门路径" aria-label="Permalink to &quot;入门路径&quot;">​</a></h2><ol><li>先看 <a href="/Encyclopedia/10-计算机基础/计算机组成/CPU与指令执行">CPU与指令执行</a>：弄懂 CPU 到底怎么&quot;读程序&quot;。</li><li>再看 <a href="/Encyclopedia/10-计算机基础/计算机组成/内存与存储层次">内存与存储层次</a>：弄懂为什么有缓存、内存、硬盘三层，以及访问方式对速度的影响。</li><li>然后进入 <a href="/Encyclopedia/10-计算机基础/操作系统/操作系统">操作系统</a>：看软件如何管理这些硬件。</li></ol><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/10-计算机基础/计算机基础">计算机基础</a>、<a href="/Encyclopedia/10-计算机基础/计算机组成/CPU与指令执行">CPU与指令执行</a>、<a href="/Encyclopedia/10-计算机基础/计算机组成/内存与存储层次">内存与存储层次</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/操作系统">操作系统</a>、<a href="/Encyclopedia/10-计算机基础/数据表示/十六进制">十六进制</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Wikipedia: Von Neumann architecture（<a href="https://en.wikipedia.org/wiki/Von_Neumann_architecture%EF%BC%89" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Von_Neumann_architecture）</a></li><li>《深入理解计算机系统》（CSAPP，书籍，只做推荐不摘录）</li></ul>`,44)])])}const u=t(l,[["render",n]]);export{k as __pageData,u as default};
